import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Whenever the AI names a machine, a team or a work order, it is an object link:
 * a dot and an underlined name that opens exactly that thing.
 * `missing`: the object was removed; the name stays readable, struck through.
 */
export interface ObjectLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  missing?: boolean
}

export function ObjectLink({ missing = false, className, children, ...props }: ObjectLinkProps) {
  return (
    <a
      data-slot="object-link"
      aria-disabled={missing || undefined}
      className={cn(
        "inline-flex cursor-pointer items-center gap-1.5 text-link underline decoration-1 underline-offset-[3px] outline-none transition-[text-decoration-thickness,background-color] duration-150 hover:bg-link/8 hover:decoration-2 focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground",
        "before:size-1.5 before:shrink-0 before:rounded-full before:bg-current before:content-[''] before:transition-transform before:duration-[260ms] before:ease-spring hover:before:scale-[1.4]",
        missing && "pointer-events-none cursor-default text-muted-foreground line-through before:bg-transparent before:shadow-[inset_0_0_0_1px_currentColor]",
        className
      )}
      {...props}
    >
      {children}
    </a>
  )
}
